/* Helper — footer for a playback state, a current name and a notice */
static void footer(playback_state_t pb, const char *name, uint8_t rec_left_s, const char *notice)
{
    sv_sd_in_t in = { true, true, true, false, pb == PLAYBACK_RECORDING,
                      (uint8_t)((pb == PLAYBACK_PLAYING) ? 1U : ((pb == PLAYBACK_PAUSED) ? 2U : 0U)),
                      "Ready", name, false };
    ui_init(&s);
    s.playback = pb;
    sv_build_footer(&s, &in, rec_left_s, notice, false, &ftr);
}

void test_F01_recording_counts_down_from_10_s(void)
{
    char want[32];

    for (unsigned left = 10U; left >= 1U; left--) {
        footer(PLAYBACK_RECORDING, "REC03.WAV", (uint8_t)left, NULL);
        snprintf(want, sizeof(want), "REC 0:%02u REC03.WAV", left);
        snprintf(msg, sizeof(msg), "%u s left", left);
        assert_padded(want, ftr.line1, SV_LINE1_W);
        TEST_ASSERT_EQUAL_INT_MESSAGE(SV_RED, ftr.line1_colour, msg);
    }
    footer(PLAYBACK_RECORDING, "REC03.WAV", 75U, NULL);       /* minutes too */
    snprintf(msg, sizeof(msg), "75 s left");
    assert_padded("REC 1:15 REC03.WAV", ftr.line1, SV_LINE1_W);
}

