void test_F10_line1_follows_the_ui_not_jacks_status(void)
{
    /* Line 1 says what the Record and Play screens say (s->playback), also
     * while Jack's status still disagrees: just after a command he has not
     * acted on yet, or after he refused one. Only the chip follows Jack. */
    static const playback_state_t pb[] = { PLAYBACK_RECORDING, PLAYBACK_PLAYING, PLAYBACK_PAUSED };
    static const char *const want[] = { "REC 0:07 REC03.WAV", "PLAYING REC03.WAV", "PAUSED REC03.WAV" };
    static const sv_colour_t colour[] = { SV_RED, SV_GREEN, SV_YELLOW };
    sv_sd_in_t in = sd_in(true, true, "Ready");     /* Jack idle */

    in.current_name = "REC03.WAV";
    for (unsigned i = 0U; i < 3U; i++) {
        ui_init(&s);
        s.playback = pb[i];
        sv_build_footer(&s, &in, 7U, NULL, false, &ftr);
        snprintf(msg, sizeof(msg), "playback %d, Jack idle", (int)pb[i]);
        assert_padded(want[i], ftr.line1, SV_LINE1_W);
        TEST_ASSERT_EQUAL_INT_MESSAGE(colour[i], ftr.line1_colour, msg);
        TEST_ASSERT_EQUAL_STRING_MESSAGE(" SD OK ", ftr.chip.text, msg);
    }

    ui_init(&s);
    s.playback = PLAYBACK_PLAYING;
    sv_build_footer(&s, NULL, 7U, NULL, false, &ftr);   /* no status yet */
    snprintf(msg, sizeof(msg), "playing, no status");
    assert_padded("PLAYING", ftr.line1, SV_LINE1_W);
    TEST_ASSERT_EQUAL_INT_MESSAGE(SV_GREEN, ftr.line1_colour, msg);

    s.playback = PLAYBACK_IDLE;                     /* Jack still has a file open */
    for (unsigned busy = 0U; busy < 3U; busy++) {
        in.recording = (busy == 0U);
        in.playing   = (uint8_t)busy;               /* recording, playing, paused */
        sv_build_footer(&s, &in, 7U, NULL, false, &ftr);
        snprintf(msg, sizeof(msg), "idle, Jack busy %u", busy);
        assert_padded("", ftr.line1, SV_LINE1_W);
        TEST_ASSERT_EQUAL_STRING_MESSAGE("SD BUSY", ftr.chip.text, msg);
    }
}

