/* Helper — want in upper case, as size-1 text is drawn */
static void upper(char *want)
{
    for (char *c = want; *c != '\0'; c++) {
        if (*c >= 'a' && *c <= 'z') {
            *c = (char)(*c - 'a' + 'A');
        }
    }
}

