/* ═══════════════════════════════════════════════════════════════════════
 * GROUP I — Refusal notices
 * ═══════════════════════════════════════════════════════════════════════ */

/* Helper — the text for a refused REC (record) or PLAY, on a status as
 * Jack sends it */
static const char *refusal(bool record, bool present, bool mounted, const char *text, uint16_t files)
{
    sv_sd_in_t in = sd_in(present, mounted, text);
    return sv_refusal_text(record, &in, files);
}

/* The reason the SD chip implies, for the loop in I05: the refusal rules
 * are the chip's, in the same order */
static const char *reason_for_chip(const char *chip_text, bool record, uint8_t files)
{
    if (strcmp(chip_text, "SD USB ") == 0) {
        return "SD CARD ON PC";
    }
    if (strcmp(chip_text, " NO SD ") == 0) {
        return "NO SD CARD";
    }
    if (strcmp(chip_text, "SD FULL") == 0) {
        return "SD CARD FULL";
    }
    if (strcmp(chip_text, "SD WAIT") == 0) {
        return "SD NOT READY";
    }
    if (strcmp(chip_text, "SD ERR ") == 0) {
        return "SD CARD ERROR";
    }
    if (strcmp(chip_text, " SD OK ") == 0 && !record && files == 0U) {
        return "NO RECORDINGS";
    }
    return "TRY AGAIN";                             /* SD ..., SD BUSY, SD OK */
}

void test_I01_each_rule_for_rec_and_play(void)
{
    /* Each reason, on the status Jack publishes just before he refuses */
    TEST_ASSERT_EQUAL_STRING("REC: NO SD CARD",     refusal(true,  false, false, "No Card", 0U));
    TEST_ASSERT_EQUAL_STRING("PLAY: NO SD CARD",    refusal(false, false, false, "No Card", 0U));
    TEST_ASSERT_EQUAL_STRING("REC: SD CARD FULL",   refusal(true,  true,  false, "Card Full", 4U));
    TEST_ASSERT_EQUAL_STRING("PLAY: SD CARD FULL",  refusal(false, true,  false, "Card Full", 4U));
    TEST_ASSERT_EQUAL_STRING("REC: SD NOT READY",   refusal(true,  true,  false, "Card Not Ready", 0U));
    TEST_ASSERT_EQUAL_STRING("PLAY: SD NOT READY",  refusal(false, true,  false, "Card Not Ready", 0U));
    TEST_ASSERT_EQUAL_STRING("REC: SD CARD ERROR",  refusal(true,  true,  false, "Card Error", 4U));
    TEST_ASSERT_EQUAL_STRING("PLAY: SD CARD ERROR", refusal(false, true,  false, "Card Error", 4U));
    TEST_ASSERT_EQUAL_STRING("PLAY: NO RECORDINGS", refusal(false, true,  true,  "Ready", 0U));
    /* A good card that still refused: one file would not open */
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN",     refusal(false, true,  true,  "Ready", 4U));
    TEST_ASSERT_EQUAL_STRING("REC: TRY AGAIN",      refusal(true,  true,  true,  "Ready", 4U));
}

void test_I02_no_recordings_stops_play_only_on_a_good_card(void)
{
    /* REC makes the first recording, so an empty card is no reason */
    TEST_ASSERT_EQUAL_STRING("REC: TRY AGAIN",      refusal(true,  true,  true,  "Ready", 0U));
    /* The card's own trouble comes first */
    TEST_ASSERT_EQUAL_STRING("PLAY: NO SD CARD",    refusal(false, false, false, "No Card", 0U));
    TEST_ASSERT_EQUAL_STRING("PLAY: SD CARD FULL",  refusal(false, true,  false, "Card Full", 0U));
    TEST_ASSERT_EQUAL_STRING("PLAY: SD CARD ERROR", refusal(false, true,  false, "Card Error", 0U));
    /* One recording is enough, and 255 (Jack's clamp) too */
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN",     refusal(false, true,  true,  "Ready", 1U));
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN",     refusal(false, true,  true,  "Ready", 255U));
}

void test_I03_usb_mode_wins(void)
{
    /* The card handed to a PC, whatever else the status says */
    static const char *const text[] = { "USB mode", "No Card", "Card Full", "Card Not Ready",
                                        "Ready", NULL };

    for (unsigned bits = 0U; bits < 8U; bits++) {
        for (uint8_t playing = 0U; playing <= SV_PLAYING_PREPARING; playing++) {
            for (size_t t = 0U; t < sizeof(text) / sizeof(text[0]); t++) {
                for (unsigned files = 0U; files <= 1U; files++) {
                    sv_sd_in_t in = { true, (bits & 1U) != 0U, (bits & 2U) != 0U, true,
                                      (bits & 4U) != 0U, playing, text[t], "", false };
                    snprintf(msg, sizeof(msg), "bits 0x%X playing %u text %u files %u", bits,
                             (unsigned)playing, (unsigned)t, files);
                    TEST_ASSERT_EQUAL_STRING_MESSAGE("REC: SD CARD ON PC",
                                                     sv_refusal_text(true, &in, (uint8_t)files), msg);
                    TEST_ASSERT_EQUAL_STRING_MESSAGE("PLAY: SD CARD ON PC",
                                                     sv_refusal_text(false, &in, (uint8_t)files), msg);
                }
            }
        }
    }
}

void test_I04_no_status_yet_or_busy_is_try_again(void)
{
    sv_sd_in_t in = sd_in(false, false, "No Card");

    /* Before Jack's first status the fields are not trusted */
    in.have_status = false;
    in.msc_mode    = true;
    TEST_ASSERT_EQUAL_STRING("REC: TRY AGAIN",  sv_refusal_text(true, &in, 0U));
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN", sv_refusal_text(false, &in, 0U));
    TEST_ASSERT_EQUAL_STRING("REC: TRY AGAIN",  sv_refusal_text(true, NULL, 0U));
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN", sv_refusal_text(false, NULL, 0U));

    /* Still busy with a file: the first recording on an empty card is
     * not "no recordings" */
    in = sd_in(true, true, "Recording");
    in.recording = true;
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN", sv_refusal_text(false, &in, 0U));
    TEST_ASSERT_EQUAL_STRING("REC: TRY AGAIN",  sv_refusal_text(true, &in, 0U));
    in = sd_in(true, true, "Paused");
    in.playing = 2U;
    TEST_ASSERT_EQUAL_STRING("REC: TRY AGAIN",  sv_refusal_text(true, &in, 3U));
}

void test_I05_every_input_mix_fits_and_agrees_with_the_chip(void)
{
    /* Every status, file count and command: the text starts with the
     * refused command, is upper case, fits footer line 1 and gives the
     * reason the SD chip beside it shows */
    static const char *const text[] = { "No Card", "Card Not Ready", "Ready", "Card Error",
                                        "Card Full", "USB mode", "Recording", "Playing",
                                        "Paused", "Ready (fake)", "...", "", "Something new",
                                        NULL };
    static const uint8_t files[] = { 0U, 1U, 255U };
    unsigned cases = 0U;

    for (unsigned bits = 0U; bits < 64U; bits++) {
        for (uint8_t playing = 0U; playing <= SV_PLAYING_PREPARING; playing++) {
            for (size_t t = 0U; t < sizeof(text) / sizeof(text[0]); t++) {
                for (size_t n = 0U; n < sizeof(files) / sizeof(files[0]); n++) {
                    for (int rec = 0; rec <= 1; rec++) {
                        sv_sd_in_t in = { (bits & 1U) != 0U, (bits & 2U) != 0U, (bits & 4U) != 0U,
                                          (bits & 8U) != 0U, (bits & 16U) != 0U, playing, text[t], "",
                                          (bits & 32U) != 0U };
                        const char *prefix = rec ? "REC: " : "PLAY: ";
                        const char *got    = sv_refusal_text(rec != 0, &in, files[n]);

                        sv_sd_chip(&in, &chip);
                        snprintf(msg, sizeof(msg), "bits 0x%02X playing %u text %u files %u rec %d",
                                 bits, (unsigned)playing, (unsigned)t, (unsigned)files[n], rec);
                        TEST_ASSERT_NOT_NULL_MESSAGE(got, msg);
                        TEST_ASSERT_LESS_OR_EQUAL_UINT_MESSAGE(SV_LINE1_W, strlen(got), msg);
                        TEST_ASSERT_EQUAL_INT_MESSAGE(0, strncmp(got, prefix, strlen(prefix)), msg);
                        TEST_ASSERT_EQUAL_STRING_MESSAGE(reason_for_chip(chip.text, rec != 0, files[n]),
                                                         got + strlen(prefix), msg);
                        for (const char *c = got; *c != '\0'; c++) {
                            TEST_ASSERT_FALSE_MESSAGE(*c >= 'a' && *c <= 'z', msg);
                        }
                        cases++;
                    }
                }
            }
        }
    }
    TEST_ASSERT_EQUAL_UINT(64U * 4U * 14U * 3U * 2U, cases);
}

void test_I06_every_notice_shows_whole_in_orange(void)
{
    /* One status for each reason, for REC and for PLAY: line 1 shows the
     * text uncut, over the transport line, in orange */
    static const sv_sd_in_t status[] = {
        { true,  true,  false, true,  false, 0U, "USB mode",       "",   false },
        { true,  false, false, false, false, 0U, "No Card",        "",   false },
        { true,  true,  false, false, false, 0U, "Card Full",      "",   false },
        { true,  true,  false, false, false, 0U, "Card Not Ready", "",   false },
        { true,  true,  false, false, false, 0U, "Card Error",     "",   false },
        { true,  true,  true,  false, false, 0U, "Ready",          "",   false },   /* 0 files */
        { false, false, false, false, false, 0U, NULL,             NULL, false },   /* none yet */
    };

    for (size_t i = 0U; i < sizeof(status) / sizeof(status[0]); i++) {
        for (int rec = 0; rec <= 1; rec++) {
            const char *notice = sv_refusal_text(rec != 0, &status[i], 0U);
            ui_init(&s);
            s.playback = PLAYBACK_PLAYING;
            sv_build_footer(&s, &status[i], SV_REC_LEFT_UNKNOWN, notice, false, &ftr);
            snprintf(msg, sizeof(msg), "status %u rec %d", (unsigned)i, rec);
            assert_padded(notice, ftr.line1, SV_LINE1_W);
            TEST_ASSERT_EQUAL_INT_MESSAGE(SV_ORANGE, ftr.line1_colour, msg);
        }
    }
}

void test_I07_notice_shows_for_exactly_3_s(void)
{
    /* From the refusal at t0 up to t0 + SV_NOTICE_MS - 1, gone from
     * t0 + SV_NOTICE_MS on. From the fourth start point on, the tick
     * count passes 0x80000000 or wraps to 0 during the notice or the 3 s
     * after it */
    static const uint32_t t0s[] = { 0U, 1U, 123456U, 0x7FFFFFFFU - 999U, 0x7FFFFFFFU,
                                    0xFFFFFFFFU - SV_NOTICE_MS, 0xFFFFFFFFU - 999U, 0xFFFFF000U,
                                    0xFFFFFFFFU };

    for (size_t i = 0U; i < sizeof(t0s) / sizeof(t0s[0]); i++) {
        uint32_t until = t0s[i] + SV_NOTICE_MS;
        for (uint32_t dt = 0U; dt <= 2U * SV_NOTICE_MS; dt++) {
            if ((int)sv_notice_active(t0s[i] + dt, until) != (int)(dt < SV_NOTICE_MS)) {
                snprintf(msg, sizeof(msg), "t0 0x%08lX dt %lu", (unsigned long)t0s[i], (unsigned long)dt);
                TEST_FAIL_MESSAGE(msg);
            }
        }
    }
}

void test_I08_expiry_across_the_tick_wrap(void)
{
    /* Refused 1 s before the tick count wraps: the notice ends 2 s after */
    uint32_t t0    = 0xFFFFFFFFU - 999U;
    uint32_t until = t0 + SV_NOTICE_MS;

    TEST_ASSERT_EQUAL_UINT32(2000U, until);
    TEST_ASSERT_TRUE(sv_notice_active(t0, until));
    TEST_ASSERT_TRUE(sv_notice_active(0xFFFFFFFFU, until));     /* just before the wrap */
    TEST_ASSERT_TRUE(sv_notice_active(0U, until));              /* just after */
    TEST_ASSERT_TRUE(sv_notice_active(1999U, until));
    TEST_ASSERT_FALSE(sv_notice_active(2000U, until));
    TEST_ASSERT_FALSE(sv_notice_active(2001U, until));

    /* It can end exactly at tick 0 */
    TEST_ASSERT_TRUE(sv_notice_active(0xFFFFFFFFU, 0U));
    TEST_ASSERT_FALSE(sv_notice_active(0U, 0U));

    /* Once ended it stays ended for 2^31 - 1 ms (24.8 days); the firmware
     * drops it at the end, so the flip after that never shows */
    TEST_ASSERT_FALSE(sv_notice_active(until + 0x7FFFFFFFU, until));
}

void test_I09_256_files_are_not_no_recordings(void)
{
    /* Jack counts every file on the card now: 256 must not wrap to 0 */
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN",     refusal(false, true, true, "Ready", 256U));
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN",     refusal(false, true, true, "Ready", 65535U));
    TEST_ASSERT_EQUAL_STRING("PLAY: NO RECORDINGS", refusal(false, true, true, "Ready", 0U));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP J — Answers to REC, PLAY and DELETE
 * ═══════════════════════════════════════════════════════════════════════ */

static sv_notice_t note;

/* Helper — a status on a PC (USB mode), as Jack sends it */
static sv_sd_in_t sd_on_pc(void)
{
    sv_sd_in_t in = sd_in(true, false, "USB mode");
    in.msc_mode = true;
    return in;
}

/* Helper — leave an older refusal in note, text and pop-up: the notice the
 * next answer must overwrite completely (tony_ui.c passes one it has not
 * cleared) */
static void note_holds_a_refusal(void)
{
    sv_sd_in_t no_card = sd_in(false, false, "No Card");

    sv_answer_notice(SV_CMD_PLAY, false, (uint8_t)SV_ACK_FAILED, &no_card, 0U, "", &note);
    TEST_ASSERT_EQUAL_STRING("PLAY: NO SD CARD", note.text);
    TEST_ASSERT_TRUE(note.popup);
}

void test_J01_an_information_notice_is_light_grey(void)
{
    ui_init(&s);
    s.playback = PLAYBACK_PLAYING;
    sv_build_footer(&s, NULL, SV_REC_LEFT_UNKNOWN, "DELETED REC05.WAV", true, &ftr);
    assert_padded("DELETED REC05.WAV", ftr.line1, SV_LINE1_W);
    TEST_ASSERT_EQUAL_INT(SV_LIGHTGREY, ftr.line1_colour);
}

void test_J02_a_refusal_notice_is_orange(void)
{
    ui_init(&s);
    s.playback = PLAYBACK_PLAYING;
    sv_build_footer(&s, NULL, SV_REC_LEFT_UNKNOWN, "DELETE: SD BUSY", false, &ftr);
    assert_padded("DELETE: SD BUSY", ftr.line1, SV_LINE1_W);
    TEST_ASSERT_EQUAL_INT(SV_ORANGE, ftr.line1_colour);
}

void test_J03_an_accepted_start_ends_the_notice_or_says_no_fx(void)
{
    sv_sd_in_t in = sd_in(true, true, "Ready");

    for (int rec = 0; rec <= 1; rec++) {
        note_holds_a_refusal();                     /* the accepted start must end it */
        sv_answer_notice(rec ? SV_CMD_RECORD : SV_CMD_PLAY, true, (uint8_t)SV_ACK_NONE, &in, 3U, "", &note);
        TEST_ASSERT_EQUAL_STRING("", note.text);
        TEST_ASSERT_FALSE(note.popup);
    }
    /* PREPARING: the Play screen shows the percentage, no notice */
    note_holds_a_refusal();
    sv_answer_notice(SV_CMD_PLAY, true, (uint8_t)SV_ACK_PREPARING, &in, 3U, "", &note);
    TEST_ASSERT_EQUAL_STRING("", note.text);
    TEST_ASSERT_FALSE(note.popup);
    /* NO_FX: it plays, but without the effect: an information notice */
    sv_answer_notice(SV_CMD_PLAY, true, (uint8_t)SV_ACK_NO_FX, &in, 3U, "", &note);
    TEST_ASSERT_EQUAL_STRING("NO FX FOR THIS FILE", note.text);
    TEST_ASSERT_TRUE(note.info);
    TEST_ASSERT_FALSE(note.popup);
}

void test_J10_a_play_of_a_file_that_has_gone_has_no_popup(void)
{
    /* The list changed between the window and the PLAY: say so; the card
     * is fine, so no pop-up and no beep (the window is asked for again) */
    sv_sd_in_t in = sd_in(true, true, "Ready");

    sv_answer_notice(SV_CMD_PLAY, false, (uint8_t)SV_ACK_NOT_FOUND, &in, 3U, "", &note);
    TEST_ASSERT_EQUAL_STRING("PLAY: FILE GONE", note.text);
    TEST_ASSERT_FALSE(note.info);
    TEST_ASSERT_FALSE(note.popup);
}

void test_J04_a_refused_start_uses_the_refusal_text_and_the_popup(void)
{
    sv_sd_in_t no_card = sd_in(false, false, "No Card");
    sv_sd_in_t ready   = sd_in(true, true, "Ready");

    sv_answer_notice(SV_CMD_RECORD, false, (uint8_t)SV_ACK_FAILED, &no_card, 0U, "", &note);
    TEST_ASSERT_EQUAL_STRING("REC: NO SD CARD", note.text);
    TEST_ASSERT_FALSE(note.info);
    TEST_ASSERT_TRUE(note.popup);
    sv_answer_notice(SV_CMD_PLAY, false, (uint8_t)SV_ACK_NONE, &ready, 0U, "", &note);
    TEST_ASSERT_EQUAL_STRING("PLAY: NO RECORDINGS", note.text);
    TEST_ASSERT_TRUE(note.popup);
    sv_answer_notice(SV_CMD_PLAY, false, (uint8_t)SV_ACK_BUSY, &ready, 5U, "", &note);
    TEST_ASSERT_EQUAL_STRING(sv_refusal_text(false, &ready, 5U), note.text);
    TEST_ASSERT_TRUE(note.popup);
}

void test_J05_a_done_delete_names_the_file(void)
{
    sv_sd_in_t in = sd_in(true, true, "Ready");

    sv_answer_notice(SV_CMD_DELETE, true, (uint8_t)SV_ACK_NONE, &in, 4U, "REC05.WAV", &note);
    TEST_ASSERT_EQUAL_STRING("DELETED REC05.WAV", note.text);
    TEST_ASSERT_TRUE(note.info);
    TEST_ASSERT_FALSE(note.popup);
    sv_answer_notice(SV_CMD_DELETE, true, (uint8_t)SV_ACK_NONE, &in, 4U, "ABCDEFGH.WAV", &note);
    TEST_ASSERT_EQUAL_STRING("DELETED ABCDEFGH.WAV", note.text);       /* 20 characters */
}

void test_J06_a_busy_delete_is_worded_by_the_status(void)
{
    sv_sd_in_t on_pc = sd_on_pc();
    sv_sd_in_t busy  = sd_in(true, true, "Recording");
    busy.recording = true;

    sv_answer_notice(SV_CMD_DELETE, false, (uint8_t)SV_ACK_BUSY, &on_pc, 4U, "REC05.WAV", &note);
    TEST_ASSERT_EQUAL_STRING("DELETE: SD CARD ON PC", note.text);
    sv_answer_notice(SV_CMD_DELETE, false, (uint8_t)SV_ACK_BUSY, &busy, 4U, "REC05.WAV", &note);
    TEST_ASSERT_EQUAL_STRING("DELETE: SD BUSY", note.text);
    sv_answer_notice(SV_CMD_DELETE, false, (uint8_t)SV_ACK_BUSY, NULL, 4U, "REC05.WAV", &note);
    TEST_ASSERT_EQUAL_STRING("DELETE: SD BUSY", note.text);
    TEST_ASSERT_FALSE(note.info);

    sv_answer_notice(SV_CMD_DELETE, false, (uint8_t)SV_ACK_NOT_FOUND, &busy, 4U, "REC05.WAV", &note);
    TEST_ASSERT_EQUAL_STRING("DELETE: FILE GONE", note.text);
    sv_answer_notice(SV_CMD_DELETE, false, (uint8_t)SV_ACK_FAILED, &busy, 4U, "REC05.WAV", &note);
    TEST_ASSERT_EQUAL_STRING("DELETE: CARD ERROR", note.text);
}

void test_J07_a_delete_answer_never_opens_the_popup(void)
{
    sv_sd_in_t status[3];
    status[0] = sd_in(true, true, "Ready");
    status[1] = sd_in(false, false, "No Card");
    status[2] = sd_on_pc();

    for (size_t i = 0U; i < 3U; i++) {
        for (int ok = 0; ok <= 1; ok++) {
            for (uint8_t detail = 0U; detail <= (uint8_t)SV_ACK_FAILED + 1U; detail++) {
                sv_answer_notice(SV_CMD_DELETE, ok != 0, detail, &status[i], 0U, "REC05.WAV", &note);
                snprintf(msg, sizeof(msg), "status %u ok %d detail %u", (unsigned)i, ok, (unsigned)detail);
                TEST_ASSERT_FALSE_MESSAGE(note.popup, msg);
                TEST_ASSERT_NOT_EQUAL_MESSAGE(0, (int)strlen(note.text), msg);   /* always says something */
            }
        }
    }
}

void test_J08_every_answer_text_fits_footer_line_1(void)
{
    static const sv_cmd_t cmds[] = { SV_CMD_RECORD, SV_CMD_PLAY, SV_CMD_DELETE };
    sv_sd_in_t status[4];
    status[0] = sd_in(true, true, "Ready");
    status[1] = sd_in(false, false, "No Card");
    status[2] = sd_on_pc();
    status[3] = sd_in(true, false, "Card Not Ready");

    for (size_t c = 0U; c < 3U; c++) {
        for (size_t i = 0U; i < 4U; i++) {
            for (int ok = 0; ok <= 1; ok++) {
                for (uint8_t detail = 0U; detail <= (uint8_t)SV_ACK_FAILED; detail++) {
                    sv_answer_notice(cmds[c], ok != 0, detail, &status[i], 0U, "ABCDEFGH.WAV", &note);
                    snprintf(msg, sizeof(msg), "cmd %u status %u ok %d detail %u", (unsigned)c,
                             (unsigned)i, ok, (unsigned)detail);
                    TEST_ASSERT_LESS_OR_EQUAL_UINT_MESSAGE(SV_LINE1_W, strlen(note.text), msg);
                }
            }
        }
    }
}

void test_J09_the_answer_is_null_safe(void)
{
    sv_answer_notice(SV_CMD_DELETE, true, (uint8_t)SV_ACK_NONE, NULL, 0U, NULL, &note);
    TEST_ASSERT_EQUAL_STRING("DELETED ", note.text);
    sv_answer_notice(SV_CMD_PLAY, false, (uint8_t)SV_ACK_NONE, NULL, 0U, NULL, &note);
    TEST_ASSERT_EQUAL_STRING("PLAY: TRY AGAIN", note.text);         /* no status yet */
    sv_answer_notice(SV_CMD_PLAY, false, (uint8_t)SV_ACK_NONE, NULL, 0U, NULL, NULL);
    TEST_PASS();
}

